explanation.code:
def count_up(limit):
    n = 1
    while n <= limit:
        yield n
        n += 1

for number in count_up(3):
    print(number)

examples.code:
def squares(limit):
    for n in range(limit):
        yield n * n

for value in squares(5):
    print(value)

print(list(squares(5)))

def long_lines(path):
    with open(path) as f:
        for line in f:
            if len(line) > 80:
                yield line

